/**
 * 播放速度控制插件
 */

import type { MpvPlugin } from '../../core/types/plugin';
import { ControlPlugin, ControlPluginOptions } from '../base/ControlPlugin';
import styles from './styles.css?inline';

export interface SpeedPluginOptions extends ControlPluginOptions {
    position?: 'left' | 'right';
    order?: number;
    /** 可選速度列表 */
    speeds?: number[];
}

const DEFAULT_SPEEDS = [8, 4, 3, 2, 1.75, 1.5, 1, 0.75, 0.5, 0.25];

export const SpeedPlugin: MpvPlugin<SpeedPluginOptions> = {
    name: 'speed',
    version: '1.0.0',
    styles,

    install(player, options = {}) {
        return new SpeedManager(player, {
            position: options.position ?? 'right',
            order: options.order ?? 0,
            speeds: options.speeds ?? DEFAULT_SPEEDS,
        });
    },
};

export class SpeedManager extends ControlPlugin<Required<SpeedPluginOptions>> {
    readonly name = 'speed';

    // DO NOT initialize these fields here! JavaScript field initializers run AFTER super(),
    // which would reset values set during createEl() back to null.
    private speedBtn!: HTMLButtonElement | null;
    private speedMenu!: HTMLElement | null;
    /** 緩存菜單項元素，避免重複 querySelectorAll */
    private menuItems!: HTMLElement[];

    protected createEl(): HTMLElement {
        const container = document.createElement('div');
        container.className = 'vp-speed-container';

        const menuItemsHtml = this.options.speeds.map(speed => {
            const isActive = speed === 1 ? 'active' : '';
            return `<div class="vp-menu-item ${isActive}" data-speed="${speed}">${speed}x</div>`;
        }).join('');

        container.innerHTML = `
            <button class="vp-btn vp-speed-btn" title="播放速度">1x</button>
            <div class="vp-speed-menu vp-menu">${menuItemsHtml}</div>
        `;

        this.speedBtn = container.querySelector('.vp-speed-btn');
        this.speedMenu = container.querySelector('.vp-speed-menu');
        // 緩存菜單項元素，只查詢一次
        this.menuItems = Array.from(this.speedMenu?.querySelectorAll('.vp-menu-item') ?? []) as HTMLElement[];

        this.bindEvents(container);

        // 初始化 UI 狀態
        this.updateUI();

        return container;
    }

    private bindEvents(container: HTMLElement): void {
        // Hover 顯示選單
        this.on(container, 'mouseenter', () => this.speedMenu?.classList.add('show'));
        this.on(container, 'mouseleave', () => this.speedMenu?.classList.remove('show'));

        // 點擊速度選項（使用緩存的 menuItems）
        for (const item of this.menuItems) {
            this.on(item, 'click', (e) => {
                e.stopPropagation();
                const speed = parseFloat(item.dataset.speed || '1');
                this.player.playbackRate = speed;
                this.speedMenu?.classList.remove('show');
            });
        }

        // 監聽速度變化
        this.onPlayer('ratechange', () => this.updateUI());
    }

    private updateUI(): void {
        const rate = this.player.playbackRate;

        if (this.speedBtn) {
            this.speedBtn.textContent = `${rate}x`;
        }

        // 更新選單中的 active 狀態（使用緩存的 menuItems）
        for (const item of this.menuItems) {
            const itemSpeed = parseFloat(item.dataset.speed || '1');
            item.classList.toggle('active', itemSpeed === rate);
        }
    }
}

